	-- updating color scheme for minor civs
	-- Maritime
	UPDATE MinorCivilizations SET DefaultPlayerColor = 'PLAYERCOLOR_MINOR_ADEJE' WHERE Type = 'MINOR_CIV_ADEJE' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='COLORS-UCS' AND Value= 1);
	UPDATE MinorCivilizations SET DefaultPlayerColor = 'PLAYERCOLOR_MINOR_AUCKLAND' WHERE Type = 'MINOR_CIV_AUCKLAND' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='COLORS-UCS' AND Value= 1);
	UPDATE MinorCivilizations SET DefaultPlayerColor = 'PLAYERCOLOR_MINOR_CHEVAK' WHERE Type = 'MINOR_CIV_CHEVAK' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='COLORS-UCS' AND Value= 1);
